        rows=grid.size;
        columns=grid[0].size;
        var boxRow=0;
        var boxColumn=0;
        var playerRow=0;
        var playerColumn=0;
        for(r in 0 until rows)for(c in 0 until columns)when(grid[r][c]){
            'B'->{
                boxRow=r;
                boxColumn=c
            };
            'S'->{
                playerRow=r;
                playerColumn=c
            };
            'T'->{
                targetRow=r;
                targetColumn=c
            }
        };
        val queue=java.util.ArrayDeque<IntArray>();
        val seen=mutableSetOf<Int>();
        queue.addLast(intArrayOf(boxRow,boxColumn,playerRow,playerColumn,0));
        seen.add(key(boxRow,boxColumn,playerRow,playerColumn));
        while(queue.isNotEmpty()){
            val state=queue.removeFirst();
            if(state[0]==targetRow&&state[1]==targetColumn)return state[4];
            val reachable=reachable(state[2],state[3],state[0],state[1]);
            for(direction in directions){
                val nextBoxRow=state[0]+direction[0];
                val nextBoxColumn=state[1]+direction[1];
                val standRow=state[0]-direction[0];
                val standColumn=state[1]-direction[1];
                if(open(nextBoxRow,nextBoxColumn)&&open(standRow,standColumn)&&reachable[standRow][standColumn]){
                    val code=key(nextBoxRow,nextBoxColumn,state[0],state[1]);
                    if(seen.add(code))queue.addLast(intArrayOf(nextBoxRow,nextBoxColumn,state[0],state[1],state[4]+1))
                }
            }
        };
        return -1
    };
    private fun reachable(startRow:Int,startColumn:Int,boxRow:Int,boxColumn:Int):Array<BooleanArray>{
        val seen=Array(rows){
            BooleanArray(columns)
        };
        val queue=java.util.ArrayDeque<IntArray>();
        queue.addLast(intArrayOf(startRow,startColumn));
        seen[startRow][startColumn]=true;
        while(queue.isNotEmpty()){
            val cell=queue.removeFirst();
            for(direction in directions){
                val r=cell[0]+direction[0];
                val c=cell[1]+direction[1];
                if(open(r,c)&&!seen[r][c]&&(r!=boxRow||c!=boxColumn)){
                    seen[r][c]=true;
                    queue.addLast(intArrayOf(r,c))
                }
            }
        };
        return seen
    };
    private fun open(r:Int,c:Int)=r in 0 until rows&&c in 0 until columns&&grid[r][c]!='#';
    private fun key(br:Int,bc:Int,pr:Int,pc:Int)=((br*columns+bc)*rows+pr)*columns+pc
}

