class Solution {
    vector<vector<char>>* grid;
    int rows,columns,targetRow,targetColumn;
    int directions[4][2]={
        {
            1,0
        },{
            -1,0
        },{
            0,1
        },{
            0,-1
        }
    };
    bool open(int r,int c){
        return r>=0&&r<rows&&c>=0&&c<columns&&(*grid)[r][c]!='#';
    }
    int key(int br,int bc,int pr,int pc){
        return ((br*columns+bc)*rows+pr)*columns+pc;
    }
    vector<vector<bool>> reachable(int startRow,int startColumn,int boxRow,int boxColumn){
        vector<vector<bool>> seen(rows,vector<bool>(columns));
        queue<pair<int,int>> pending;
        pending.push({
            startRow,startColumn
        });
        seen[startRow][startColumn]=true;
        while(!pending.empty()){
            auto [row,column]=pending.front();
            pending.pop();
            for(auto& direction:directions){
                int r=row+direction[0],c=column+direction[1];
                if(open(r,c)&&!seen[r][c]&&(r!=boxRow||c!=boxColumn)){
                    seen[r][c]=true;
                    pending.push({
                        r,c
                    });
                }
            }
        }
        return seen;
    }
    public:int minPushBox(vector<vector<char>>& input){
        grid=&input;
        rows=input.size();
        columns=input[0].size();
        int boxRow=0,boxColumn=0,playerRow=0,playerColumn=0;
        for(int r=0;r<rows;++r)for(int c=0;c<columns;++c)if(input[r][c]=='B'){
            boxRow=r;
            boxColumn=c;
        }else if(input[r][c]=='S'){
            playerRow=r;
            playerColumn=c;
        }else if(input[r][c]=='T'){
            targetRow=r;
            targetColumn=c;
        }
        queue<array<int,5>> pending;
        unordered_set<int> seen;
        pending.push({
            boxRow,boxColumn,playerRow,playerColumn,0
        });
        seen.insert(key(boxRow,boxColumn,playerRow,playerColumn));
        while(!pending.empty()){
            auto state=pending.front();
            pending.pop();
            if(state[0]==targetRow&&state[1]==targetColumn)return state[4];
            auto canReach=reachable(state[2],state[3],state[0],state[1]);
            for(auto& direction:directions){
                int nextBoxRow=state[0]+direction[0],nextBoxColumn=state[1]+direction[1],standRow=state[0]-direction[0],standColumn=state[1]-direction[1];
                if(open(nextBoxRow,nextBoxColumn)&&open(standRow,standColumn)&&canReach[standRow][standColumn]){
                    int code=key(nextBoxRow,nextBoxColumn,state[0],state[1]);
                    if(seen.insert(code).second)pending.push({
                        nextBoxRow,nextBoxColumn,state[0],state[1],state[4]+1
                    });
                }
            }
        }
        return -1;
    }
};
